INSERT INTO `trivia_questions` (`questionNumber`,`question`,`answerA`,`answerB`,`answerC`,`correctAnswer`,`explanation`,`image`,`category`) VALUES
(1,'Warum hat Emmentaler Löcher?','Sie werden beim Formen mit Nadeln gestochen','Bakterien produzieren Kohlendioxid im Käse','Beim Reifen verdunstet Flüssigkeit aus Hohlräumen','B','Verantwortlich sind Propionsäurebakterien. Sie bauen während der Reifung Milchsäure ab und setzen dabei Kohlendioxid frei. Das Gas kann aus dem festen Laib nicht entweichen und sammelt sich an winzigen Keimstellen – daraus werden die runden Löcher, im Fachjargon »Nester«.\n\nInteressant ist, was passiert, wenn man zu sauber arbeitet: Früher dienten kleine Heupartikel in der Milch als Keimstellen. Seit moderne Melkanlagen praktisch partikelfreie Milch liefern, werden die Löcher messbar kleiner. Manche Käsereien geben deshalb bewusst wieder Heustaub zu.','assets/quiz-illustrations/emmentaler.svg','Essen & Trinken'),
(2,'Warum sind Bananen krumm?','Die Frucht wächst gegen die Schwerkraft nach oben','Das Gewicht des Fruchtbündels biegt sie nach unten','Die Schale trocknet einseitig und zieht sich zusammen','A','Der Blütenstand der Bananenstaude hängt zunächst nach unten. Die jungen Früchte wachsen dann gegen die Schwerkraft dem Licht entgegen wieder nach oben – Botaniker nennen das negativen Gravitropismus. Weil sie unten ansetzen und oben enden, entsteht der Bogen.\n\nDie Krümmung ist damit kein Zuchtergebnis, sondern eine gewöhnliche Wachstumsreaktion. Wildbananen sind genauso krumm – nur stecken sie voller harter Kerne und sind kaum essbar.',NULL,'Natur'),
(3,'Warum brennt Chili im Mund, obwohl nichts heiß ist?','Der Scharfstoff ätzt die Schleimhaut leicht an','Er erhöht kurzzeitig die Temperatur im Mundraum','Er reizt genau die Nerven, die Hitze melden','C','Der Scharfstoff Capsaicin dockt an einen Rezeptor namens TRPV1 an. Der ist eigentlich ein Hitzemelder und feuert normalerweise ab etwa 43 Grad. Capsaicin öffnet ihn auf chemischem Weg – das Gehirn bekommt also eine echte Hitzemeldung, ohne dass irgendwo Wärme im Spiel ist.\n\nDeshalb hilft Wasser kaum: Capsaicin ist fettlöslich. Milch, Joghurt oder Sahne binden es dagegen wirksam. Und weil Vögel diesen Rezeptor anders gebaut haben, schmecken ihnen Chilis überhaupt nicht scharf – für die Pflanze praktisch, denn Vögel verbreiten die Samen unbeschadet.','assets/quiz-illustrations/chili.svg','Körper'),
(4,'Warum muss man beim Zwiebelschneiden weinen?','Der intensive Geruch löst einen Reflex im Gehirn aus','Zwiebelsaft reizt mechanisch die Hornhaut','Ein Gas bildet auf dem Auge eine Säure','C','Wird die Zwiebel verletzt, treffen zwei Stoffe zusammen, die vorher getrennt in der Zelle lagen. Ein Enzym baut daraus eine flüchtige Schwefelverbindung. Die steigt auf und reagiert auf der feuchten Augenoberfläche zu einer schwachen Säure. Das Auge spült mit Tränen nach.\n\nDas erklärt auch, warum die Hausmittel funktionieren: Eine gekühlte Zwiebel gibt weniger Gas ab, ein scharfes Messer zerstört weniger Zellen, und wer nah am Abzug arbeitet, bekommt weniger davon ans Auge.',NULL,'Essen & Trinken'),
(5,'Warum hat ein Golfball Dellen?','Sie verringern den Luftwiderstand deutlich','Sie machen den Ball im Gras besser sichtbar','Sie verbessern den Griff beim Abschlag','A','Ein glatter Ball reißt die Luftströmung früh ab und zieht ein breites Sog-Gebiet hinter sich her. Die Dellen erzeugen eine dünne, verwirbelte Schicht direkt an der Oberfläche, die der Kontur länger folgt. Das Sog-Gebiet wird kleiner, der Widerstand sinkt – und der Rückwärtsdrall erzeugt zusätzlich Auftrieb.\n\nDer Effekt ist gewaltig: Ein glatter Golfball fliegt nur etwa halb so weit. Entdeckt wurde er zufällig, weil Spieler im 19. Jahrhundert merkten, dass ihre alten, zerschrammten Bälle besser flogen als die neuen.','assets/quiz-illustrations/golfball.svg','Technik'),
(6,'Warum sind Tennisbälle gelb?','Wegen der Sichtbarkeit im Farbfernsehen','Gelb bleibt auf Sand am längsten sauber','Der Farbstoff macht den Filz widerstandsfähiger','A','Bis in die 1970er-Jahre waren Tennisbälle weiß. Mit dem Farbfernsehen wurde das zum Problem: Vor hellen Linien und weißer Kleidung war der Ball auf dem Bildschirm schlecht zu verfolgen. Untersuchungen zeigten, dass ein knalliges Grüngelb am besten zu erkennen war. Der Weltverband erlaubte es 1972.\n\nWimbledon blieb trotzdem noch bis 1986 beim weißen Ball – Tradition. Die offizielle Farbbezeichnung lautet übrigens »optic yellow«, und ob der Ball nun gelb oder grün ist, darüber streiten Zuschauer bis heute.',NULL,'Geschichte'),
(7,'Warum wird im Flugzeug bei Start und Landung das Kabinenlicht gedimmt?','Damit die Augen an Dunkelheit angepasst sind','Um Strom für die Triebwerke zu sparen','Damit die Piloten weniger Reflexionen im Cockpit haben','A','Start und Landung sind die kritischen Phasen. Müsste man bei Dunkelheit evakuieren, bräuchten Augen, die sich gerade noch an helles Kabinenlicht gewöhnt haben, mehrere Minuten, um draußen etwas zu erkennen. Bei gedimmtem Licht sind sie schon vorangepasst.\n\nAus dem gleichen Grund müssen die Fensterblenden offen bleiben: Die Crew soll von innen sehen können, ob auf einer Seite Feuer oder Trümmer liegen, bevor sie eine Tür öffnet. Und die Notbeleuchtung verläuft am Boden, weil sie dort auch bei Rauch sichtbar bleibt.',NULL,'Technik'),
(8,'Warum hat jedes Flugzeugfenster unten ein kleines Loch?','Damit die Scheibe innen nicht beschlägt','Es sorgt dafür, dass die äußere Scheibe den Druck trägt','Es dient als Ablauf für Kondenswasser','B','Ein Kabinenfenster besteht aus mehreren Acrylscheiben. Das winzige Loch in der mittleren Scheibe verbindet den Zwischenraum mit der Kabine. Dadurch liegt der gesamte Druckunterschied zur dünnen Außenluft auf der äußeren Scheibe, die genau dafür konstruiert ist. Die mittlere ist die Reserve, falls die äußere versagt.\n\nAls Nebeneffekt entweicht Feuchtigkeit aus dem Zwischenraum, so dass die Scheiben nicht von innen vereisen. Beides gleichzeitig zu erledigen ist gute Ingenieurskunst mit einem Bohrloch.','assets/quiz-illustrations/flugzeugfenster.svg','Technik'),
(9,'Warum ist das Meer salzig?','Flüsse tragen gelöstes Gestein hinein','Unterseeische Salzlager lösen sich langsam auf','Meeresorganismen geben stetig Salze ab','A','Regen ist leicht säuerlich und löst beim Abfließen Mineralien aus dem Gestein. Flüsse transportieren diese Salze ins Meer. Wasser verdunstet von dort wieder – die Salze bleiben. Über Jahrmillionen hat sich so ein Gehalt von rund 35 Gramm pro Liter eingestellt. Unterseeische Vulkanquellen liefern einen zweiten Beitrag.\n\nWarum wird es dann nicht immer salziger? Weil Salze auch wieder verschwinden: Sie werden in Sedimente eingebaut, in abgeschnittenen Meeresbecken abgelagert und mit den Erdplatten in die Tiefe gezogen. Zufuhr und Abfuhr halten sich ungefähr die Waage.',NULL,'Natur'),
(10,'Was knackt, wenn man mit den Fingerknöcheln knackt?','Eine Gasblase in der Gelenkflüssigkeit','Sehnen springen über einen Knochenvorsprung','Knorpelflächen reiben kurz aufeinander','A','Zieht man das Gelenk auseinander, wächst der Spalt schneller, als Flüssigkeit nachlaufen kann. Der Druck fällt, und gelöste Gase bilden schlagartig eine Blase. Dieses Entstehen der Blase erzeugt das Geräusch – MRT-Aufnahmen haben es inzwischen im Film festgehalten.\n\nDeshalb geht es nicht sofort noch einmal: Erst muss sich das Gas wieder lösen, das dauert etwa 20 Minuten. Und die verbreitete Warnung stimmt so nicht – Studien fanden bei Dauer-Knackern keine erhöhte Arthroserate, allenfalls etwas weniger Griffkraft.',NULL,'Körper'),
(11,'Wie viele Herzen hat ein Oktopus?','Drei','Zwei, eines je Körperhälfte','Eines, aber mit vier Kammern','A','Zwei Kiemenherzen pumpen das Blut jeweils durch eine Kieme, ein größeres Hauptherz schickt es anschließend durch den Körper. Das ist nötig, weil der Sauerstoffträger im Oktopusblut, das kupferhaltige Hämocyanin, deutlich ineffizienter arbeitet als unser eisenhaltiges Hämoglobin. Es macht das Blut übrigens bläulich.\n\nDas Hauptherz setzt beim Schwimmen aus – einer der Gründe, warum Oktopusse lieber über den Boden laufen als schwimmen. Schwimmen macht sie schlicht schneller müde.',NULL,'Tiere'),
(12,'Warum frieren Pinguine nicht an den Füßen fest?','Zu- und abfließendes Blut tauschen Wärme','Ihre Fußsohlen sind mit Fett isoliert','Sie halten die Füße dauerhaft leicht angehoben','A','In den Beinen liegen Arterien und Venen dicht beieinander und gegenläufig. Das warme Blut aus dem Körper gibt seine Wärme direkt an das kalte, zurücklaufende Blut ab. Unten ankommen tut es nur noch knapp über dem Gefrierpunkt – gerade warm genug, um nicht festzufrieren, und kalt genug, dass kaum Wärme verloren geht.\n\nDieses Gegenstromprinzip nutzen auch Enten auf dem Eis, Wale in ihren Flossen und Rentiere in den Beinen. Der Pinguin kann den Blutfluss zusätzlich regulieren – an warmen Tagen lässt er mehr Wärme über die Füße ab.','assets/quiz-illustrations/pinguin.svg','Tiere'),
(13,'Welche Farbe hat die Haut eines Eisbären?','Hellgrau mit weißen Flecken','Rosa wie bei anderen Bären','Schwarz','C','Unter dem Fell ist die Haut des Eisbären schwarz – gut zu sehen an Nase und Lippen. Dunkle Haut nimmt Wärme besser auf. Die Haare selbst sind nicht weiß, sondern farblos und lichtdurchlässig. Sie erscheinen weiß, weil das Licht in ihnen gestreut wird, ähnlich wie bei Schnee oder Zuckerwatte.\n\nDeshalb können Eisbären in Zoos grünlich werden: Setzen sich Algen in den hohlen Haaren fest, schimmert das Fell grün. Die verbreitete Idee, die Haare würden Sonnenlicht wie Lichtleiter zur Haut führen, gilt heute als widerlegt.',NULL,'Tiere'),
(14,'Warum ist der Himmel blau?','Er spiegelt die Farbe der Ozeane','Luftmoleküle streuen blaues Licht am stärksten','Wasserdampf filtert rotes Licht heraus','B','Sonnenlicht enthält alle Farben. An den Molekülen der Luft wird kurzwelliges Licht viel stärker in alle Richtungen gestreut als langwelliges – dieser Zusammenhang heißt Rayleigh-Streuung. Blau kommt daher aus dem ganzen Himmel, nicht nur direkt von der Sonne.\n\nViolett würde sogar noch stärker gestreut, aber die Sonne strahlt davon weniger ab und unsere Augen sind dafür unempfindlicher. Und abends? Dann läuft das Licht schräg durch viel mehr Luft, das Blau ist unterwegs herausgestreut – übrig bleiben Orange und Rot.','assets/quiz-illustrations/himmelblau.svg','Natur'),
(15,'Warum schwimmt Eis auf Wasser?','Wasser wird beim Erstarren leichter','Die Oberflächenspannung hält es oben','Eingeschlossene Luftbläschen tragen es','A','Fast alle Stoffe werden beim Erstarren dichter. Wasser nicht: Die Moleküle ordnen sich im Eis zu einem weitmaschigen Gitter mit Hohlräumen. Eis nimmt dadurch etwa neun Prozent mehr Platz ein als dieselbe Menge flüssiges Wasser – also schwimmt es. Am dichtesten ist Wasser bei rund vier Grad.\n\nDiese Dichteanomalie ist einer der Gründe, warum Leben in Seen den Winter übersteht: Die Eisdecke bildet sich oben und isoliert, unten bleibt es bei vier Grad flüssig. Würde Eis absinken, würden Seen von unten zufrieren.','assets/quiz-illustrations/eis.svg','Physik'),
(16,'Warum sind Kanaldeckel rund?','Weil Rohre rund sind und der Deckel dazu passt','Weil runde Deckel nicht in den Schacht fallen können','Weil sich runde Deckel besser gießen lassen','B','Ein Kreis hat in jeder Richtung denselben Durchmesser. Ein runder Deckel lässt sich deshalb nicht so drehen, dass er durch seine eigene Öffnung rutscht – bei einem quadratischen Deckel genügt es, ihn diagonal zu stellen. Für Arbeiter unter der Straße ist das ein handfestes Sicherheitsargument.\n\nDazu kommt Praktisches: Runde Deckel muss man beim Einsetzen nicht ausrichten, sie lassen sich rollen statt tragen, und die runde Form leitet das Gewicht darüberfahrender Lastwagen gleichmäßig in den Rand – Ecken wären Schwachstellen.','assets/quiz-illustrations/kanaldeckel.svg','Alltag'),
(17,'Woher stammt der Name der Funktechnik Bluetooth?','Von einem blauen Bauteil im ersten Prototyp','Von einem dänischen König','Von einem Codenamen für blaue Kabel bei Ericsson','B','Pate ist Harald Blauzahn, der im 10. Jahrhundert dänische Stammesgebiete vereinte und Norwegen anband. Ein Ingenieur schlug den Namen als Arbeitstitel vor: So wie der König Volksstämme vereinte, sollte die Technik verschiedene Geräte vereinen. Der Arbeitstitel blieb, weil sich das Marketing nicht auf etwas anderes einigen konnte.\n\nSogar das Logo passt: Es kombiniert die altnordischen Runen für H und B – die Initialen des Königs. Woher der Beiname Blauzahn kam, ist unklar; vielleicht von einem dunklen, abgestorbenen Zahn.',NULL,'Sprache'),
(18,'Warum haben Jeans an den Taschen kleine Metallnieten?','Sie sind ein Erkennungszeichen für echte Markenware','Sie verstärken die Stellen, an denen der Stoff reißt','Sie leiten statische Aufladung ab','B','Der Schneider Jacob Davis flickte Arbeitshosen für Goldsucher und ärgerte sich, dass immer die Taschenecken aufgingen. Er setzte kurzerhand Nieten aus der Pferdegeschirr-Werkstatt ein. Weil ihm das Geld für ein Patent fehlte, tat er sich 1873 mit seinem Stofflieferanten Levi Strauss zusammen – aus dieser Niete wurde die moderne Jeans.\n\nEine Niete verschwand später wieder: die am Schritt. Sie wurde am Lagerfeuer unangenehm heiß. Und die kleine fünfte Tasche vorn war einmal die Tasche für die Taschenuhr.',NULL,'Alltag'),
(19,'Warum sehen wir vom Mond immer dieselbe Seite?','Seine Drehung dauert genauso lang wie ein Umlauf','Er dreht sich gar nicht','Die Erde verdeckt die andere Seite mit ihrem Schatten','A','Der Mond rotiert durchaus – nur braucht er dafür genauso lange wie für eine Runde um die Erde, etwa 27 Tage. Deshalb zeigt er uns stets dasselbe Gesicht. Diese gebundene Rotation ist kein Zufall: Die Gezeitenkräfte der Erde haben seine Drehung über Jahrmillionen abgebremst, bis sie einrastete.\n\nGanz starr ist der Anblick nicht. Weil die Mondbahn leicht elliptisch und gekippt ist, schaukelt er ein wenig hin und her. Über die Zeit werden dadurch rund 59 Prozent seiner Oberfläche von der Erde aus sichtbar.','assets/quiz-illustrations/mond.svg','Weltall'),
(20,'Warum gibt es Jahreszeiten?','Weil die Erdachse geneigt ist','Weil der Abstand zur Sonne schwankt','Weil die Sonne unterschiedlich stark strahlt','A','Die Erdachse steht um gut 23 Grad schief. Dadurch trifft das Sonnenlicht die Nordhalbkugel im Juni steiler und länger, im Dezember flacher und kürzer – auf der Südhalbkugel genau umgekehrt. Steiler heißt: Dieselbe Energie verteilt sich auf weniger Fläche.\n\nDer Abstand kann es schon deshalb nicht sein, weil dann überall gleichzeitig Sommer wäre. Tatsächlich ist die Erde Anfang Januar der Sonne am nächsten – mitten im europäischen Winter.','assets/quiz-illustrations/jahreszeiten.svg','Weltall'),
(21,'Warum funkeln Sterne, Planeten aber kaum?','Planeten leuchten nicht selbst, sondern reflektieren nur','Sterne ändern ihre Helligkeit tatsächlich ständig','Planeten erscheinen als Scheibchen, Sterne als Punkt','C','Das Funkeln entsteht nicht am Stern, sondern in unserer Atmosphäre: Luftschichten unterschiedlicher Temperatur brechen das Licht verschieden und lenken es hin und her. Ein Stern ist selbst im Teleskop nur ein Lichtpunkt – wird der abgelenkt, sieht man es sofort.\n\nEin Planet dagegen steht so nah, dass er ein winziges Scheibchen bildet, also viele Punkte nebeneinander. Deren Schwankungen mitteln sich weg, das Licht bleibt ruhig. Ein praktischer Trick am Nachthimmel: Was ruhig steht, ist meist ein Planet.',NULL,'Physik'),
(22,'Warum wird Honig praktisch nie schlecht?','Bienen setzen ein natürliches Konservierungsmittel zu','Es ist zu wenig freies Wasser darin, als dass Keime wachsen','Der hohe Zuckergehalt tötet Keime chemisch ab','B','Reifer Honig enthält nur um 17 Prozent Wasser, und das ist durch den Zucker fest gebunden. Mikroorganismen brauchen freies Wasser – in Honig entzieht ihnen die Umgebung stattdessen Flüssigkeit. Dazu ist Honig säuerlich und enthält geringe Mengen Wasserstoffperoxid, das die Bienen über ein Enzym einbringen.\n\nIn ägyptischen Gräbern wurde Honig gefunden, der nach Jahrtausenden noch nicht verdorben war. Verdünnt man ihn aber, fällt der Schutz weg und er beginnt zu gären – genau das nutzt man beim Herstellen von Honigwein.',NULL,'Essen & Trinken'),
(23,'Warum sprudelt Cola so heftig, wenn man Mentos hineinwirft?','Die Bonbons reagieren chemisch mit der Säure','Ihre raue Oberfläche bietet unzählige Blasenkeime','Sie lösen sich schlagartig auf und verdrängen Flüssigkeit','B','Kohlensäurehaltige Getränke sind mit Gas übersättigt. Damit sich eine Blase bilden kann, braucht es einen Startpunkt. Die Mentos-Oberfläche ist unter dem Mikroskop voller Poren und Kanten – tausende Startpunkte auf einmal. Das Gas entweicht in Sekunden und schiebt die Flüssigkeit als Fontäne nach oben.\n\nEine chemische Reaktion ist es nicht. Zusatzstoffe in den Bonbons senken zusätzlich die Oberflächenspannung, was die Blasenbildung weiter erleichtert. Mit Light-Cola wird die Fontäne höher, weil sie ohne Zuckersirup dünnflüssiger ist.',NULL,'Essen & Trinken'),
(24,'Warum schrumpelt die Haut an den Fingern im Wasser?','Die Haut saugt sich mit Wasser voll und dehnt sich','Hautfett wird ausgewaschen und die Haut fällt ein','Das Nervensystem verengt aktiv die Blutgefäße','C','Man würde ein reines Aufquellen erwarten – tatsächlich ist es eine gesteuerte Reaktion. Das autonome Nervensystem verengt die Blutgefäße unter der Haut, das Volumen darunter nimmt ab, und die feste Hornschicht wirft Falten. Der Beweis: Ist der zuständige Nerv verletzt, schrumpeln die Finger nicht mehr.\n\nWarum der Körper das tut, ist nicht endgültig geklärt. Experimente deuten darauf hin, dass die Rillen nasse Gegenstände besser greifen lassen – ähnlich wie das Profil eines Reifens Wasser abführt.',NULL,'Körper'),
(25,'Warum bekommen Vögel auf einer Stromleitung keinen Schlag?','Ihre Krallen sind aus isolierendem Material','Federn leiten Strom nicht weiter','Zwischen ihren Füßen liegt kaum Spannung','C','Strom fließt nur, wenn es einen Spannungsunterschied gibt. Beide Füße des Vogels sitzen auf demselben Draht, wenige Zentimeter voneinander entfernt – dazwischen liegt fast keine Spannung, also fließt so gut wie kein Strom durch den Vogel. Der bequemere Weg bleibt das Kupfer.\n\nGefährlich wird es, sobald der Vogel zusätzlich etwas anderes berührt: einen zweiten Draht, einen Mast oder ein geerdetes Bauteil. Genau deshalb sind große Vogelarten mit weiter Spannweite an Hochspannungsmasten besonders bedroht.','assets/quiz-illustrations/vogel-leitung.svg','Tiere'),
(26,'Woher kommt die Redewendung »aus dem Stegreif«?','Vom Steigbügel des Reiters','Von einem Reif, den Handwerker als Maß nutzten','Von einem Steg, über den man ohne Umweg ging','A','»Stegreif« ist ein altes Wort für Steigbügel. Wer eine Sache aus dem Stegreif erledigte, tat es, ohne vom Pferd zu steigen – also sofort, ohne Vorbereitung, im Vorbeireiten. Weil das Wort außer in dieser Wendung ausgestorben ist, wird es heute oft falsch als »Stehgreif« geschrieben.\n\nEine verwandte Wendung aus derselben Welt: etwas aus dem Handgelenk schütteln. Und wer »hoch zu Ross« saß, tat das ganz wörtlich – mit dem entsprechenden Blick von oben.',NULL,'Sprache'),
(27,'Was bedeutete der Wunsch »Hals- und Beinbruch« ursprünglich?','Eine Warnung vor gefährlicher Arbeit','Einen Trinkspruch der Bergleute','Einen Segen aus dem Jiddischen','C','Dahinter steht sehr wahrscheinlich die jiddische Formel »hatslokhe un brokhe« – Glück und Segen. Deutsche Ohren hörten daraus lautlich »Hals und Bruch«, und weil das keinen Sinn ergab, machte der Volksmund einen vollständigen Unglückswunsch daraus.\n\nDas passte gut zu einem verbreiteten Aberglauben: Wer offen Glück wünscht, ruft das Gegenteil herbei – also wünscht man lieber Schlimmes. Im Englischen tut man genau dasselbe mit »break a leg«.',NULL,'Sprache'),
(28,'Warum steht auf Rettungswagen vorn die Aufschrift spiegelverkehrt?','Weil die Folie so einfacher von innen zu kleben ist','Damit sie im Rückspiegel richtig zu lesen ist','Es ist eine internationale Vorgabe für Blaulichtfahrzeuge','B','Die Schrift auf der Front ist für den Fahrer des vorausfahrenden Autos gedacht. Der sieht das Fahrzeug im Rückspiegel – und dort erscheint jede Schrift seitenverkehrt. Wird sie von Anfang an gespiegelt aufgebracht, liest er sie im Spiegel korrekt und kann schneller reagieren.\n\nDeshalb steht die Spiegelschrift auch immer nur vorn, nie an den Seiten oder hinten: Nur die Front landet überhaupt im Rückspiegel anderer.',NULL,'Alltag'),
(29,'Warum gefährdet ein Blitzeinschlag die Insassen eines Flugzeugs nicht?','Die Gummireifen isolieren das Flugzeug','Die Höhe schwächt den Blitz so stark ab','Die Metallhülle leitet den Strom außen herum','C','Die leitende Außenhaut wirkt als faradayscher Käfig: Der Strom läuft über die Oberfläche und verlässt das Flugzeug an einer Ableitspitze wieder, während der Innenraum praktisch feldfrei bleibt. Verkehrsflugzeuge werden statistisch etwa einmal im Jahr getroffen, meist merken die Passagiere nur Knall und Lichtblitz.\n\nAufwendig ist das bei modernen Rumpfteilen aus Kohlefaser, die schlechter leiten. Dort werden feine Metallgitter oder Kupferfolien einlaminiert, damit der Käfig weiter funktioniert. Zusätzlich sitzen kleine Entladungsspitzen an Flügel- und Leitwerkskanten.','assets/quiz-illustrations/blitz-flugzeug.svg','Physik'),
(30,'Warum sind Flamingos rosa?','Die Farbe stammt aus ihrer Nahrung','Das Federkleid enthält einen eigenen roten Farbstoff','Die Federstruktur bricht das Licht rosa','A','Flamingos filtern Kleinkrebse und Algen aus dem Wasser. Darin stecken Carotinoide – dieselbe Stoffgruppe, die Karotten orange macht. Der Vogel baut sie in Haut und Federn ein. Ohne diese Kost bleibt er blassweiß, was in Zoos früher regelmäßig zu sehen war, bevor das Futter angepasst wurde.\n\nDie Farbe ist auch ein Signal: Kräftiges Rosa zeigt, dass ein Tier gut frisst und gesund ist – entsprechend attraktiv wirkt es bei der Partnerwahl. Brütende Eltern verblassen dagegen, weil sie Farbstoffe an ihre Küken abgeben.',NULL,'Natur'),
(31,'Warum riecht der Urin nach dem Verzehr von Spargel?','Der Körper baut eine Spargelsäure zu Schwefelverbindungen ab','Der Spargel enthält selbst stark riechende Öle','Spargel entwässert und macht den Urin dadurch konzentrierter','A','Spargel enthält Asparagusinsäure, die es in dieser Form in kaum einem anderen Lebensmittel gibt. Die Verdauung zerlegt sie in kleine, leicht flüchtige Schwefelverbindungen. Weil sie so flüchtig sind, riecht man sie schon nach etwa einer Viertelstunde.\n\nDas Kuriose: Nicht jeder nimmt den Geruch wahr. Eine verbreitete Genvariante im Riechvermögen macht einen erheblichen Teil der Menschen dafür blind. Lange dachte man deshalb, nur manche Leute würden den Geruch überhaupt produzieren – tatsächlich tun es fast alle.',NULL,'Körper'),
(32,'Warum schmeckt Orangensaft direkt nach dem Zähneputzen scheußlich?','Die Zahnpasta reagiert mit der Fruchtsäure','Das Menthol betäubt die Zunge vollständig','Ein Schaumbildner blockiert die Süßwahrnehmung','C','Verantwortlich ist meist Natriumlaurylsulfat, der Stoff, der die Zahnpasta schäumen lässt. Er dämpft die Rezeptoren für Süß und greift gleichzeitig Fettmoleküle an, die sonst die Bitterwahrnehmung abmildern. Ergebnis: Die Süße des Saftes fehlt, die Säure und die Bitterstoffe bleiben – und schmecken plötzlich unerträglich.\n\nZahnpasta ohne diesen Schaumbildner löst den Effekt kaum aus. Wer nicht warten will, kann das Frühstück auch einfach vor dem Zähneputzen erledigen.',NULL,'Körper'),
(33,'Warum kommt Ketchup erst nicht und dann schwallweise aus der Flasche?','Luft muss erst in die Flasche nachströmen','Die enge Öffnung staut ihn zunächst auf','Er wird durch Schütteln dünnflüssiger','C','Ketchup gehört zu den nichtnewtonschen Flüssigkeiten. In Ruhe bilden die Tomatenpartikel ein lockeres Netz, das ihn fast wie einen Feststoff zusammenhält. Wirkt genug Kraft – Schütteln, Klopfen, Druck – bricht dieses Netz zusammen und die Zähigkeit sinkt binnen Sekunden dramatisch. Dann fließt alles auf einmal.\n\nDas Verhalten heißt Thixotropie und wird gezielt genutzt: Wandfarbe soll unter dem Pinsel dünn sein und an der Wand nicht tropfen, Zahnpasta soll in der Tube stehen und auf Druck herauskommen.','assets/quiz-illustrations/ketchup.svg','Physik'),
(34,'Warum rostet Edelstahl nicht, obwohl er vor allem aus Eisen besteht?','Er ist mit einer aufgetragenen Schutzschicht überzogen','Das Eisen wird durch Legieren chemisch unangreifbar','Enthaltenes Chrom bildet selbst eine hauchdünne Sperrschicht','C','Ab etwa zwölf Prozent Chrom passiert etwas Elegantes: Das Chrom reagiert an der Oberfläche sofort mit Sauerstoff zu einer nur wenige Atomlagen dünnen, dichten Oxidschicht. Die sitzt fest, ist unsichtbar und lässt keinen Sauerstoff mehr an das Eisen darunter. Rost braucht aber genau diesen Zugang.\n\nDas Beste daran ist die Selbstheilung: Kratzt man die Schicht auf, bildet sie sich in Sekunden neu. Nur wenn Sauerstoff dauerhaft fehlt – etwa unter einer festsitzenden Ablagerung – oder Chlorid sie lokal durchbricht, kann auch Edelstahl korrodieren.','assets/quiz-illustrations/edelstahl.svg','Technik'),
(35,'Warum sind die Buchstaben auf der Tastatur so unpraktisch angeordnet?','Die Anordnung folgt der Buchstabenhäufigkeit im Englischen','Sie stammt von der Anordnung im Telegrafenalphabet','Sie sollte das Verhaken der Schreibmaschinenhebel verhindern','C','In mechanischen Schreibmaschinen schlugen Typenhebel von unten gegen das Papier. Lagen zwei häufig aufeinanderfolgende Buchstaben nebeneinander, verhakten sich die Hebel bei schnellem Anschlag. Christopher Latham Sholes zog deshalb in den 1870er-Jahren häufige Buchstabenpaare räumlich auseinander. Das Ergebnis ist die QWERTY-Reihe, deutsch mit getauschtem Z und Y.\n\nMit Computern ist der Grund entfallen, geblieben ist die Anordnung trotzdem: Millionen Menschen hatten sie gelernt. Nachweislich schnellere Layouts wie Dvorak oder Neo haben sich nie durchgesetzt.','assets/quiz-illustrations/qwertz.svg','Technik'),
(36,'Warum fährt man in Großbritannien links?','Wegen der Lenkung der ersten dort gebauten Autos','Weil die Eisenbahn dort links fuhr und die Straßen folgten','Damit Reiter die Schwerthand zum Gegenverkehr hatten','C','Die gängige Erklärung reicht weit vor das Auto zurück. Wer beritten unterwegs war und ein Schwert trug, führte es rechts. Ritt man links, blieb die Waffenhand dem Gegenüber zugewandt – und man konnte die rechte Hand zum Grüßen oder zum Griff nutzen, ohne die Zügel zu wechseln. Papst Bonifatius VIII. soll Pilgern im Jahr 1300 links zu gehen empfohlen haben.\n\nDass ein großer Teil der Welt heute rechts fährt, hat viel mit Frankreich und den USA zu tun: Breite Fuhrwerke mit mehreren Zugpferden wurden vom linken hinteren Pferd aus gelenkt – der Kutscher wollte den Gegenverkehr links neben sich sehen und hielt sich deshalb rechts.',NULL,'Geschichte'),
(37,'Warum hat eine Woche sieben Tage?','Weil sich ein Mondmonat sauber in vier Teile teilen lässt','Wegen der sieben mit dem Auge sichtbaren Wandelsterne','Weil sieben in Babylon als göttliche Zahl gilt','B','Babylonische Astronomen kannten sieben Himmelskörper, die sich vor dem Sternenhintergrund bewegen: Sonne, Mond, Merkur, Venus, Mars, Jupiter und Saturn. Jedem wurde ein Tag zugeordnet. Über Griechen und Römer kam die Siebentagewoche nach Europa – anders als Monat und Jahr hat sie also keinen astronomischen Takt, dem sie folgen müsste.\n\nDie Namen verraten die Herkunft bis heute. Im Englischen sind Saturday, Sunday und Monday direkt Saturn, Sonne und Mond. Im Deutschen stecken germanische Götter darin, die die römischen ersetzten: Dienstag von Tiu, Donnerstag von Donar, Freitag von Frija.',NULL,'Geschichte'),
(38,'Warum heißt der Mittwoch nicht nach einem Gott wie die übrigen Wochentage?','Weil er in der Antike als Ruhetag ohne Gottheit galt','Weil die Kirche den Namen des Gottes Wodan verdrängte','Weil er erst im Mittelalter zur Woche hinzukam','B','Ursprünglich war es der Tag des Gottes Wodan – im Englischen heißt er noch heute Wednesday, im Niederländischen woensdag. Im deutschen Sprachraum setzte die Kirche im Frühmittelalter die nüchterne Zählform durch: der Tag in der Mitte der Woche.\n\nBeim Samstag hat sie es teilweise auch geschafft. Der Norden sagt Sonnabend, also Vorabend des Sonntags, der Süden Samstag – das kommt über Umwege vom hebräischen Sabbat. Nur beim Dienstag, Donnerstag und Freitag blieben die alten Götternamen stehen.',NULL,'Sprache'),
(39,'Warum haben Sektkorken die Form eines Pilzes?','Sie werden so gepresst, damit man sie besser greifen kann','Sie sind zylindrisch und werden erst in der Flasche verformt','Der Pilzkopf verteilt den Druck des Drahtkorbs','B','Vor dem Verkorken ist ein Sektkorken ein dicker Zylinder, deutlich breiter als der Flaschenhals. Beim Verschließen wird er stark zusammengedrückt. Der untere Teil bleibt im Hals gefangen und behält die zusammengedrückte Form, der obere Teil federt außerhalb wieder auf – daraus wird der Pilzkopf.\n\nAn der Form lässt sich sogar das Alter ablesen: Je länger die Flasche liegt, desto weniger elastisch ist der Kork und desto schmaler bleibt der herausgezogene Korken. Ein fast zylindrischer Korken deutet auf einen lange gelagerten Sekt.','assets/quiz-illustrations/sektkorken.svg','Essen & Trinken'),
(40,'Warum haben Weingläser einen langen Stiel?','Damit die Hand den Wein nicht erwärmt','Damit das Glas beim Schwenken stabiler steht','Damit sich die Aromen im Stiel sammeln','A','Am Stiel gehalten, bleibt die Handwärme vom Wein weg – bei einem gekühlten Weißwein macht das über ein längeres Essen mehrere Grad aus. Nebeneffekt: Der Kelch bleibt frei von Fingerabdrücken und beschlägt nicht, man sieht Farbe und Klarheit besser.\n\nDeshalb gehört zu einem Cognacschwenker gerade kein langer Stiel: Dort ist die Handwärme gewollt, sie treibt die Aromen aus. Und moderne stiellose Gläser sind ein bewusster Kompromiss – bequemer zu spülen, dafür wärmt die Hand mit.',NULL,'Essen & Trinken'),
(41,'Warum knurrt der Magen?','Magensäure brodelt bei leerem Magen','Gas und Flüssigkeit werden durch den Darm geschoben','Die Magenwand vibriert vor Anspannung','B','Magen und Darm arbeiten auch ohne Nahrung: Etwa alle eineinhalb bis zwei Stunden läuft eine kräftige Reinigungswelle durch den Verdauungstrakt und schiebt Reste weiter. Trifft sie auf ein Gemisch aus Flüssigkeit und Luft, entstehen die gurgelnden Geräusche, die Mediziner Borborygmus nennen.\n\nDass es bei leerem Magen so laut ist, hat einen einfachen Grund: Es fehlt der Inhalt, der den Schall dämpft. Voll knurrt es genauso, man hört es nur nicht.',NULL,'Körper'),
(42,'Was passiert im Körper beim Schluckauf?','Die Speiseröhre verkrampft sich ringförmig','Der Magen drückt kurzzeitig gegen die Lunge','Das Zwerchfell zuckt und die Stimmbänder schlagen zu','C','Ein Reflex lässt das Zwerchfell ruckartig zusammenziehen – man zieht unwillkürlich Luft ein. Nur einen Bruchteil einer Sekunde später schließt der Kehlkopf die Stimmbänder. Die einströmende Luft trifft auf den Verschluss, und genau das erzeugt den typischen Ton.\n\nWarum es diesen Reflex gibt, ist unklar; eine Vermutung führt ihn auf Kaulquappen zurück, die beim Kiemenatmen etwas Ähnliches tun. Die Hausmittel haben immerhin ein gemeinsames Prinzip: Luft anhalten, Wasser trinken oder Kaltes schlucken erhöhen den CO₂-Gehalt oder reizen den beteiligten Nerv – beides kann den Reflex unterbrechen.',NULL,'Körper'),
(43,'Warum bekommt man Kopfschmerzen, wenn man Eis zu schnell isst?','Das Gehirn kühlt kurzzeitig messbar ab','Gefäße am Gaumen reagieren und der Schmerz wird falsch verortet','Der Zucker lässt den Blutdruck kurz einbrechen','B','Kälte am Gaumen lässt Blutgefäße erst zusammenziehen und dann schnell weiten. Diese Reaktion registriert der Trigeminusnerv – derselbe Nerv, der auch große Bereiche des Gesichts und der Stirn versorgt. Das Gehirn kann die Meldung nicht genau zuordnen und verlegt den Schmerz nach vorn in die Stirn. Fachleute sprechen von übertragenem Schmerz.\n\nDas Gehirn selbst kühlt dabei nicht ab, es hat auch keine Schmerzrezeptoren. Der Spuk ist nach höchstens einer halben Minute vorbei; wer die Zunge an den Gaumen presst, wärmt die Stelle und verkürzt ihn.',NULL,'Körper'),
(44,'Warum hört man in einer großen Muschel ein Rauschen wie am Meer?','Man hört das eigene Blut in den Ohrgefäßen','Eingeschlossene Luft schwingt in einer festen Tonhöhe','Die Muschel verstärkt leise Umgebungsgeräusche','C','Der Hohlraum der Muschel ist ein Resonanzkörper. Er greift aus dem allgegenwärtigen leisen Geräuschteppich der Umgebung bestimmte Frequenzen heraus und verstärkt sie – heraus kommt ein breitbandiges Rauschen, das dem Meer ähnelt. Ein Becher oder eine hohle Hand am Ohr tun genau dasselbe.\n\nDie Blut-Erklärung lässt sich leicht widerlegen: In einem sehr stillen Raum wird das Rauschen deutlich schwächer, und beim Treppensteigen mit schnellem Puls wird es nicht lauter. Wäre es das eigene Blut, müsste es umgekehrt sein.',NULL,'Körper'),
(45,'Warum wird man seekrank?','Der Luftdruck an Deck verändert den Innendruck des Ohrs','Die Schwankungen bringen den Magen mechanisch aus dem Takt','Das Gleichgewichtsorgan meldet etwas anderes als die Augen','C','Unter Deck sieht das Auge eine ruhende Kabine, das Gleichgewichtsorgan im Innenohr spürt aber Schaukeln. Das Gehirn kann die widersprüchlichen Meldungen nicht zusammenbringen. Eine gängige Erklärung: Es deutet den Konflikt als Vergiftung – und die sinnvolle Reaktion auf eine Vergiftung ist Erbrechen.\n\nDaraus folgen die wirksamen Gegenmittel unmittelbar: an Deck gehen und den Horizont ansehen, damit Augen und Innenohr dasselbe melden. Aus dem gleichen Grund wird dem Fahrer selten schlecht, dem Beifahrer mit Buch dagegen schnell.',NULL,'Körper'),
(46,'Warum kann eine Eule den Kopf so weit drehen?','Weil sich ihre Augen nicht bewegen lassen','Ihr Schädel sitzt beweglich auf einem Kugelgelenk','Damit sie beim Fliegen nach hinten sehen kann','A','Eulenaugen sind für maximale Lichtstärke riesig und keine Kugeln, sondern Röhren – sie füllen die Augenhöhle vollständig aus und sind praktisch unbeweglich. Die Eule kann also nicht mit den Augen blicken, sie muss den ganzen Kopf drehen. Dafür hat sie 14 Halswirbel, doppelt so viele wie ein Mensch, und schafft rund 270 Grad.\n\nDie Blutversorgung ist an dieses Extrem angepasst: Die Arterien verlaufen in weiten Kanälen und haben Reservepolster, so dass sie beim starken Verdrehen nicht abgeklemmt werden. Ein Mensch würde bei derselben Bewegung die Durchblutung des Gehirns unterbrechen.','assets/quiz-illustrations/eule.svg','Tiere'),
(47,'Warum haben Ziegen rechteckige Pupillen?','Um bei praller Sonne weniger Licht einzulassen','Damit sie Farben besser unterscheiden können','Für ein sehr breites Blickfeld ohne Kopfdrehung','C','Der waagerechte Schlitz wirkt wie ein Panoramaformat: Er lässt Licht aus einem sehr weiten horizontalen Winkel herein und liefert am Boden ein scharfes Bild, während oben und unten wenig verloren geht. Zusammen mit den seitlich sitzenden Augen kommt die Ziege auf ein Blickfeld von annähernd 320 Grad – sie sieht grasend fast rundum, ohne den Kopf zu heben.\n\nDas Muster passt zur Lebensweise: Weidende Beutetiere wie Ziegen, Schafe und Pferde haben waagerechte Pupillen. Katzen als lauernde Jäger haben senkrechte Schlitze, die Entfernungen besser einschätzen lassen. Und beim Grasen bleibt der Schlitz waagerecht – das Auge dreht mit dem gesenkten Kopf gegen.','assets/quiz-illustrations/ziegenpupille.svg','Tiere'),
(48,'Wie erzeugt ein Glühwürmchen sein Licht?','Durch Reibung feiner Chitinplatten','Durch Bakterien, die im Hinterleib leben','Durch eine chemische Reaktion mit Sauerstoff','C','Im Hinterleib bringt ein Enzym den Stoff Luciferin mit Sauerstoff zusammen. Die Energie der Reaktion wird fast vollständig als Licht abgegeben, kaum als Wärme – deshalb der Name Kaltes Licht. Der Wirkungsgrad liegt bei rund 40 Prozent und schlägt jede Glühbirne um Längen.\n\nDas Blinken ist eine Partnerannonce, und jede Art hat ihren eigenen Takt. Bei den heimischen Leuchtkäfern sitzen meist die flugunfähigen Weibchen im Gras und leuchten, während die Männchen fliegend suchen. Manche amerikanischen Arten treiben es weiter: Ihre Weibchen imitieren den Takt fremder Arten und fressen die angelockten Männchen.',NULL,'Tiere'),
(49,'Warum kann eine Fliege an der Zimmerdecke laufen?','Winzige Härchen halten über eine Flüssigkeit','Sie erzeugt mit den Beinen einen leichten Unterdruck','Ihre Krallen greifen in Unebenheiten des Putzes','A','An den Fußspitzen sitzen zwei Haftpolster mit tausenden feinster Härchen. Jedes gibt eine winzige Menge einer öligen Flüssigkeit ab. Der dünne Flüssigkeitsfilm zieht das Härchen über Kapillarkräfte an die Oberfläche – jedes einzeln fast nichts, alle zusammen deutlich mehr als das Gewicht der Fliege.\n\nDas erklärt zwei Beobachtungen: Auf glattem Glas hält es besser als auf staubigen Flächen, weil Staub den Kontakt unterbricht. Und die Fliege muss aktiv abrollen, um sich zu lösen – festkleben und wieder loskommen sind zwei getrennte Kunststücke.','assets/quiz-illustrations/fliege.svg','Tiere'),
(50,'Welche Farbe hatten Karotten ursprünglich?','Orange, so wie heute','Violett und weiß','Grün wie ihr Kraut','B','Die Kulturmöhre stammt aus dem Raum Afghanistan und war violett, gelblich oder weiß. Orange Sorten entstanden erst in der frühen Neuzeit durch Auslese, maßgeblich in den Niederlanden. Sie enthielten viel Beta-Carotin, schmeckten milder und setzten sich in Europa durch – bis Orange als die natürliche Karottenfarbe galt.\n\nDie beliebte Erzählung, niederländische Gärtner hätten die Möhre dem Hause Oranien zu Ehren orange gezüchtet, ist hübsch, aber historisch nicht belegt. Violette Sorten sind übrigens zurück im Handel – als Neuheit.',NULL,'Natur'),
(51,'Warum wird eine angeschnittene Avocado braun?','Chlorophyll zerfällt unter Lichteinfluss','Die Fettsäuren im Fruchtfleisch werden ranzig','Ein Enzym reagiert mit Luftsauerstoff','C','Beim Schneiden werden Zellen zerstört und ein Enzym namens Polyphenoloxidase trifft auf Sauerstoff. Es baut pflanzliche Inhaltsstoffe zu braunen Pigmenten um – dieselbe Reaktion färbt aufgeschnittene Äpfel, Bananen und Kartoffeln. Verdorben ist die Frucht dadurch nicht.\n\nDas Enzym braucht Sauerstoff und mag Säure nicht. Deshalb funktionieren Zitronensaft und luftdichtes Abdecken, und deshalb hilft es, das Fruchtfleisch beim Guacamole direkt mit Limette zu mischen. Der Kern im Dip hält dagegen nur die Fläche frei, die er selbst bedeckt.',NULL,'Essen & Trinken'),
(52,'Warum wird Brot im Kühlschrank besonders schnell altbacken?','Es trocknet dort schneller aus als bei Zimmertemperatur','Die Stärke kristallisiert bei Kühlschranktemperatur am schnellsten','Kälte tötet die Hefen ab, die es weich halten','B','Altbackenwerden ist kein Austrocknen, sondern eine Umordnung: Die beim Backen aufgeschlossene Stärke bildet allmählich wieder feste, kristalline Bereiche und drängt Wasser aus. Der Fachbegriff ist Retrogradation. Genau dieser Vorgang läuft im Bereich weniger Grad über null am schnellsten – Kühlschranktemperatur ist der ungünstigste Punkt.\n\nDeshalb gilt: Brot bei Zimmertemperatur lagern oder gleich einfrieren, denn tief gefroren stoppt der Vorgang praktisch. Und weil er umkehrbar ist, wird altbackenes Brot im Ofen wieder weich – kurz aufbacken schmilzt die Kristalle auf.',NULL,'Essen & Trinken'),
(53,'Welcher Gipfel ist am weitesten vom Erdmittelpunkt entfernt?','Der Chimborazo in Ecuador','Der Mount Everest im Himalaya','Der Denali in Alaska','A','Die Erde ist keine Kugel, sondern durch ihre Rotation am Äquator ausgebeult – dort liegt der Meeresspiegel rund 21 Kilometer weiter außen als an den Polen. Der Chimborazo steht fast auf dem Äquator. Obwohl er mit gut 6260 Metern über dem Meer weit unter dem Everest bleibt, liegt sein Gipfel etwa zwei Kilometer weiter vom Erdmittelpunkt entfernt.\n\nHöchster Berg ist der Everest damit trotzdem, nur nach einem anderen Maßstab. Nimmt man den Fuß als Bezug, gewinnt ein Dritter: Der Mauna Kea auf Hawaii ragt vom Meeresboden gerechnet über 10.000 Meter auf – knapp die Hälfte davon liegt unter Wasser.','assets/quiz-illustrations/chimborazo.svg','Weltall'),
(54,'Warum hört man den Donner erst nach dem Blitz?','Der Donner entsteht erst kurz nach der Entladung','Schall ist rund eine Million Mal langsamer als Licht','Der Schall wird von Wolken zunächst zurückgehalten','B','Blitz und Donner entstehen gleichzeitig: Der Blitzkanal heizt die Luft binnen Mikrosekunden auf viele tausend Grad, sie dehnt sich explosionsartig aus, und diese Druckwelle ist der Donner. Das Licht braucht für die Strecke praktisch keine Zeit, der Schall etwa drei Sekunden pro Kilometer.\n\nDaraus wird die bekannte Faustregel: Sekunden zählen, durch drei teilen, Entfernung in Kilometern. Das lange Grollen kommt daher, dass der Blitzkanal kilometerlang ist – seine Abschnitte sind unterschiedlich weit entfernt, also trifft der Schall nach und nach ein.','assets/quiz-illustrations/blitz-donner.svg','Physik'),
(55,'Warum sind Wolken weiß, Regenwolken aber grau?','Dicke Wolken lassen kaum Licht nach unten durch','Regenwolken enthalten Staub, der sie dunkel färbt','Wassertropfen werden beim Wachsen dunkler','A','Wolkentröpfchen streuen alle Farben gleich stark, deshalb erscheint eine Wolke weiß. Wächst sie in die Höhe, muss das Licht immer mehr Tröpfchen passieren, wird bei jeder Streuung ein Stück abgelenkt und kommt unten kaum noch an. Von unten betrachtet wirkt die Wolke deshalb grau bis fast schwarz – nicht wegen ihrer Farbe, sondern wegen ihrer Dicke.\n\nVon oben, etwa aus dem Flugzeug, ist dieselbe Gewitterwolke strahlend weiß. Und weil große Regentropfen weniger Fläche pro Wassermenge bieten als viele kleine Tröpfchen, streut eine Wolke kurz vor dem Regen zusätzlich schwächer.',NULL,'Natur'),
(56,'Warum ist Rot international die Farbe für »Halt«?','Weil sie an Blut und damit an Gefahr erinnert','Weil frühe Signallampen nur rotes Glas hatten','Weil sie am weitesten sichtbar bleibt und selten natürlich vorkommt','C','Rotes Licht wird von Dunst und Regen weniger gestreut als blaues und ist deshalb über große Entfernungen gut zu sehen – dasselbe Prinzip, das Sonnenuntergänge rot macht. Dazu kommt, dass Rot in der Landschaft selten ist und damit auffällt. Die Eisenbahn setzte es im 19. Jahrhundert als Haltsignal durch, von dort übernahm es der Straßenverkehr.\n\nEine Farbe fiel dabei durch: Ursprünglich stand Weiß für »freie Fahrt«. Nachdem in einem Fall das rote Glas herausgefiel und der Lokführer die nackte weiße Lampe als Freigabe las, wurde daraus Grün.',NULL,'Alltag'),
(57,'Warum sind Verkehrsflugzeuge meist weiß?','Weiße Lackierungen sind besonders langlebig','Weiß bleibt im Flug am kühlsten und zeigt Schäden','Weiß ist im Radar am besten zu erfassen','B','Weiß reflektiert Sonnenlicht und hält den Rumpf am Boden deutlich kühler, was Klimaanlage und Material entlastet. Auf hellem Grund sind außerdem Risse, Ölspuren und Treibstofflecks bei der Kontrolle sofort zu sehen. Weiß verblasst zudem kaum, während kräftige Farben in Höhenstrahlung schnell ausbleichen und häufiger nachlackiert werden müssen.\n\nDazu kommt ein handfestes Argument: Vollflächige Lackierung wiegt bei einem Großflugzeug mehrere hundert Kilogramm und kostet über die Jahre Treibstoff. Einige Airlines lassen deshalb Teile bewusst blank oder lackieren so dünn wie möglich.',NULL,'Technik'),
(58,'Warum haben Einkaufswagen ein Schloss für eine Münze?','Um die Ausgabe der Wagen zählen zu können','Damit die Wagen zurückgebracht werden','Um Diebstahl der Wagen unmöglich zu machen','B','Die Münze ist ein Pfand, das nur der zurückbekommt, der den Wagen wieder einhängt. Betriebswirtschaftlich lohnt sich das nicht wegen des Geldes, sondern wegen der eingesparten Arbeitszeit: Ohne Pfand muss Personal die Wagen dauernd vom Parkplatz einsammeln, und dabei entstehen die meisten Blechschäden an Kundenautos.\n\nDer Betrag ist bewusst klein gewählt. Er muss nur groß genug sein, damit sich das Zurückschieben lohnt – nicht so groß, dass er Kunden abschreckt, die keine passende Münze dabei haben.',NULL,'Alltag'),
(59,'Woher kommt die Wendung »Schwein gehabt«?','Vom Sparschwein als Zeichen von Wohlstand','Vom Schwein als Trostpreis bei Wettkämpfen','Von einem Schweineglücksbringer der Seefahrer','B','Bei mittelalterlichen Schützen- und Sportwettbewerben erhielt der Letzte ein Schwein als Trostpreis. Wer als Verlierer immerhin ein wertvolles Tier heimtrug, hatte trotz der Niederlage Glück gehabt – daraus wurde die Wendung. Ein Schwein war Vermögen: Es lieferte Fleisch, Fett und Nachwuchs.\n\nAus derselben Wurzel stammt das Glücksschwein zum Neujahr. Das Sparschwein hingegen hat wahrscheinlich einen ganz anderen Ursprung: eine Tonart namens »pygg«, aus der man Sparbehälter formte – und die englische Lautähnlichkeit zu »pig« tat den Rest.',NULL,'Sprache'),
(60,'Warum beginnt der Tag in der Zeitrechnung um Mitternacht?','Weil die Römer den Amtstag um Mitternacht wechselten','Weil der Sonnenaufgang je nach Jahreszeit wandert','Weil die Kirche den Tag mit der Nachtmesse beginnen ließ','B','Als Beginn eines Tages sind mehrere Punkte denkbar, und historisch waren sie alle in Gebrauch: Für Ägypter und später die Römer begann der bürgerliche Tag um Mitternacht, jüdische und islamische Kalender lassen ihn mit Sonnenuntergang beginnen. Praktisch durchgesetzt hat sich Mitternacht aus einem einfachen Grund: Sonnenauf- und -untergang wandern über das Jahr und mit dem Breitengrad, Mitternacht als Gegenpunkt zum Sonnenhöchststand ist dagegen astronomisch fest definierbar.\n\nAstronomen hielten sich lange nicht daran: Bis 1925 begann ihr Tag mittags, damit eine Beobachtungsnacht nicht mitten im Datum zerfiel. Wer alte Sternkataloge liest, muss diesen Unterschied mitrechnen.',NULL,'Geschichte'),
(61,'Wie erzeugt eine Katze das Schnurren?','Durch Luft, die an den Zähnen vorbeistreicht','Durch Vibration der Kehlkopfmuskeln','Durch ein Flattern des Zwerchfells','B','Ein Signal aus dem Gehirn lässt die Muskeln am Kehlkopf etwa 25 bis 30 Mal pro Sekunde zusammenziehen. Die Stimmbänder öffnen und schließen sich dabei im Takt, und weil das beim Ein- und Ausatmen funktioniert, kann eine Katze minutenlang ohne Unterbrechung schnurren – anders als beim Miauen.\n\nSchnurren heißt nicht automatisch Wohlbefinden. Katzen schnurren auch bei Schmerzen, beim Tierarzt und im Sterben. Eine Vermutung: Die Frequenz liegt im Bereich, der in Versuchen die Knochenheilung anregt – Schnurren wäre dann auch Selbstberuhigung und vielleicht mehr.',NULL,'Tiere'),
(62,'Was steckt im Höcker eines Kamels?','Ein Wasserspeicher','Ein Geflecht aus Blutgefäßen','Fett','C','Der Höcker ist ein Fettdepot von bis zu 35 Kilogramm. Fett ist der beste Energiespeicher, den ein Körper bauen kann, und beim Verbrennen entsteht sogar etwas Wasser – der eigentliche Gewinn ist aber die Energie. Bei langem Hunger schrumpft der Höcker und kippt schlaff zur Seite.\n\nDie Wasserleistung des Kamels liegt woanders: Es lässt seine Körpertemperatur tagsüber um mehrere Grad steigen, statt zu schwitzen, und seine roten Blutkörperchen sind oval und dehnbar, so dass sie das schlagartige Trinken von über 100 Litern überstehen, ohne zu platzen.','assets/quiz-illustrations/kamel.svg','Tiere'),
(63,'Wozu dienen die großen Ohren eines afrikanischen Elefanten vor allem?','Zum besonders feinen Hören','Zum Abgeben von Körperwärme','Zum Abwehren von Insekten','B','Die Ohren sind von einem dichten Netz oberflächlicher Blutgefäße durchzogen und bieten mehrere Quadratmeter Fläche. Durch Fächeln streicht Luft daran vorbei und kühlt das Blut, bevor es zurück in den Körper fließt – bei günstigen Bedingungen um mehrere Grad. Für ein Tier dieser Masse ist Wärme loszuwerden das größere Problem als Wärme zu halten.\n\nDaran lassen sich die Arten unterscheiden: Der Afrikanische Elefant lebt in heißerer, offener Landschaft und hat deutlich größere Ohren als der Asiatische. Hören kann er ohnehin gut, allerdings vor allem sehr tiefe Töne, die er kilometerweit wahrnimmt.','assets/quiz-illustrations/elefantenohr.svg','Tiere'),
(64,'Wie viele Halswirbel hat eine Giraffe?','Sieben, genauso viele wie ein Mensch','Vierzehn','Über zwanzig, ähnlich wie ein Schwan','A','Fast alle Säugetiere haben sieben Halswirbel – die Maus, der Mensch, der Wal und eben auch die Giraffe. Bei ihr ist jeder einzelne Wirbel bis zu 25 Zentimeter lang. Die Zahl ist in der Entwicklung so streng festgelegt, dass Abweichungen beim Menschen meist mit Fehlbildungen einhergehen.\n\nAusnahmen gibt es: Faultiere kommen je nach Art auf sechs bis neun, Seekühe auf sechs. Vögel sind gar nicht gebunden, ein Schwan hat über zwanzig – deshalb ist sein Hals so beweglich, während die Giraffe ihren eher wie einen Kran bewegt.',NULL,'Tiere'),
(65,'Warum umkreisen Nachtfalter eine Lampe?','Sie halten die Lampe für den Mond und verrechnen sich','Sie werden von der Wärme der Lampe angezogen','Sie drehen instinktiv den Rücken zum hellsten Licht','C','Lange galt die Mond-Erklärung. Hochgeschwindigkeitsaufnahmen fliegender Insekten haben aber etwas anderes gezeigt: Sie halten reflexhaft ihren Rücken zur hellsten Lichtquelle. Am Himmel ist das der richtige Weg, oben zu bleiben. Neben einer Lampe kippt dieser Reflex die Flugbahn – das Tier gerät in eine enge Kurve um die Lampe, statt sie anzusteuern.\n\nDas erklärt Beobachtungen, die zur Mond-Theorie nie passten: Falter fliegen nicht direkt in die Lampe, sondern kreisen, taumeln und bleiben manchmal darunter regelrecht hängen. Für nachtaktive Insekten ist künstliches Licht damit weniger Anziehung als Orientierungsfalle.',NULL,'Tiere'),
(66,'Warum leuchten Katzenaugen im Scheinwerferlicht?','Hinter der Netzhaut sitzt eine spiegelnde Schicht','Die Netzhaut selbst gibt Licht ab','Die Hornhaut wirft das Licht wie eine Linse zurück','A','Hinter der Netzhaut liegt das Tapetum lucidum, eine Schicht aus feinen Kristallen, die Licht nach vorn zurückwirft. Was die Sehzellen beim ersten Durchgang verpasst haben, bekommen sie beim zweiten – das verbessert das Sehen in der Dämmerung erheblich. Der Rest verlässt das Auge wieder und ist als Leuchten zu sehen.\n\nDer Preis dafür ist Schärfe: Das zurückgeworfene Licht streut ein wenig, das Bild wird körniger. Menschen haben diese Schicht nicht, deshalb erscheinen unsere Augen auf Blitzbildern rot – da sieht man einfach die durchblutete Netzhaut.','assets/quiz-illustrations/katzenauge.svg','Tiere'),
(67,'Welche Form hätte eine Kerzenflamme in Schwerelosigkeit?','Sie sähe genauso aus wie auf der Erde','Sie wäre flach und breit','Sie wäre kugelförmig','C','Die spitze Form kommt allein von der Schwerkraft: Heißes Gas ist leichter, steigt auf und zieht unten kühle Luft nach. Fällt dieser Auftrieb weg, kann Sauerstoff nur noch von allen Seiten hineindiffundieren – die Flamme wird zur kleinen Kugel. Auf der Raumstation wurde das mehrfach beobachtet.\n\nSie sieht dabei auch anders aus: bläulich statt gelb und deutlich kühler. Ohne aufsteigenden Strom bekommt sie weniger Sauerstoff, es entsteht kaum Ruß – und gelb ist eine Kerzenflamme auf der Erde nur, weil glühende Rußteilchen darin leuchten.','assets/quiz-illustrations/kerze.svg','Physik'),
(68,'Wie löst Seife Fett, das Wasser allein nicht wegbekommt?','Ihre Moleküle haben ein wasser- und ein fettliebendes Ende','Sie zersetzt das Fett chemisch','Sie senkt die Temperatur, bei der Fett schmilzt','A','Ein Seifenmolekül ist ein Zwitter: ein langer fettliebender Schwanz, ein wasserliebender Kopf. Im Wasser lagern sich viele davon so um einen Fetttropfen, dass alle Schwänze im Fett stecken und alle Köpfe nach außen zeigen. Diese Kügelchen nennt man Micellen – von außen wirken sie wasserfreundlich und lassen sich einfach abspülen.\n\nDerselbe Bau macht Seife gegen viele Viren wirksam: Sie haben eine Fetthülle, und die Seifenschwänze fahren regelrecht hinein und reißen sie auf. Deshalb ist gründliches Händewaschen kein bloßes Wegspülen.','assets/quiz-illustrations/seife.svg','Alltag'),
(69,'Warum vergilbt altes Papier?','Der Leim zwischen den Fasern zerfällt','Papier nimmt mit der Zeit Staub in die Fasern auf','Holzbestandteile werden durch Luft und Licht abgebaut','C','Billiges Papier enthält Lignin, den Stoff, der Holz steif macht. Lignin reagiert mit Sauerstoff und Licht, und die Abbauprodukte sind gelblich-braun. Dazu kommt Säure aus der Herstellung, die die Zellulosefasern langsam zerlegt – das Papier wird nicht nur gelb, sondern auch brüchig.\n\nZeitungspapier vergilbt in Tagen am Fenster, gutes Buchpapier hält Jahrzehnte. Archive verwenden deshalb säurefreies, ligninarmes Papier. Und Bücher aus dem 16. Jahrhundert sind oft besser erhalten als solche von 1900: Damals wurde aus Hadern gearbeitet, nicht aus Holzschliff.',NULL,'Alltag'),
(70,'Warum hat gewöhnliches Fensterglas an der Schnittkante einen grünen Ton?','Von einer Beschichtung gegen Wärmeeinstrahlung','Von einer Grünfärbung, die Sprünge sichtbar macht','Von Eisenverunreinigungen im Sand','C','Der Quarzsand für Flachglas enthält immer Spuren von Eisen. Eisenoxid absorbiert vor allem im roten Bereich, übrig bleibt ein leichter Grünstich. Durch eine dünne Scheibe fällt das kaum auf, entlang der Kante schaut man aber durch viele Zentimeter Glas – und dort summiert sich der Effekt sichtbar.\n\nWo es auf Farbtreue ankommt, wird eisenarmer Sand verwendet: Solche Weißgläser kosten mehr und kommen bei Vitrinen, Bilderrahmen und Solarmodulen zum Einsatz. Umgekehrt lassen sich mit anderen Metallzusätzen kräftige Farben erzeugen – Kobalt für Blau, Selen für Rot.',NULL,'Physik'),
(71,'Warum klingt die eigene Stimme in einer Aufnahme so fremd?','Mikrofone geben tiefe Töne schwächer wieder','Beim Sprechen hört man sich zusätzlich über die Schädelknochen','Man hört sich selbst immer mit Verzögerung','B','Beim Sprechen erreicht der Schall das Innenohr auf zwei Wegen: durch die Luft und direkt durch Kiefer- und Schädelknochen. Der Knochenweg überträgt tiefe Frequenzen besonders gut. Man hört sich deshalb voller und dunkler, als man tatsächlich klingt. Die Aufnahme kennt nur den Luftweg – und die ist die ehrliche Version.\n\nDas ist auch der Grund, warum man beim Zuhalten der Ohren die eigene Stimme noch dröhnend hört. Sänger und Sprecher üben deshalb mit Aufnahmen: Nur so hören sie, was das Publikum hört.','assets/quiz-illustrations/stimme.svg','Körper'),
(72,'Warum kann man sich nicht selbst kitzeln?','Der Reiz erreicht das Gehirn zu langsam','Die eigene Hand berührt zu gleichmäßig','Das Kleinhirn kündigt die eigene Berührung vorher an','C','Das Kleinhirn schickt bei jeder eigenen Bewegung eine Vorhersage an die Sinnesbereiche des Gehirns: Achtung, diese Berührung kommt von uns. Was zur Vorhersage passt, wird abgeschwächt. Genau deshalb erschrickt man auch nicht über den eigenen Schritt und stört sich nicht am Gefühl der eigenen Kleidung.\n\nForscher haben den Effekt mit einem Roboterarm ausgehebelt: Baut man eine kleine Verzögerung zwischen Handbewegung und Berührung ein, kitzelt es plötzlich doch. Und Menschen mit bestimmten psychischen Erkrankungen, bei denen diese Vorhersage gestört ist, können sich sehr wohl selbst kitzeln.',NULL,'Körper'),
(73,'Warum sieht man Blutgefäße unter der Haut bläulich, obwohl Blut rot ist?','Sauerstoffarmes Blut in den Venen ist tatsächlich blau','Die Gefäßwände selbst sind bläulich gefärbt','Die Haut lässt rotes Licht anders passieren als blaues','C','Sauerstoffarmes Blut ist nicht blau, sondern dunkelrot – bei einer Blutabnahme kann man das sehen. Blau entsteht erst durch die Haut: Rotes Licht dringt tief ein und wird im Gewebe fast vollständig verschluckt, blaues wird schon in oberen Schichten zurückgestreut. Über einem dunklen Gefäß gewinnt daher der blaue Anteil.\n\nDeshalb hängt der Effekt an der Tiefe: Sehr oberflächliche Gefäße wirken rötlich, tiefere kaum sichtbar, und in der mittleren Tiefe erscheinen sie blau. Es ist derselbe Grund, aus dem Tätowierfarbe in tieferen Hautschichten bläulich schimmert.',NULL,'Körper'),
(74,'Warum müssen manche Menschen niesen, wenn sie ins helle Licht treten?','Licht trocknet die Nasenschleimhaut aus','Ein Nerv leitet den Reiz fehl','Die Pupillenbewegung reizt die Nasennebenhöhlen','B','Sehnerv und Gesichtsnerven laufen nahe beieinander, und bei einem Teil der Menschen springt der starke Lichtreiz auf die Bahn über, die den Niesreflex auslöst. Das Gehirn deutet ihn als Reizung in der Nase. Der Reflex ist erblich, betrifft je nach Untersuchung 18 bis 35 Prozent der Bevölkerung und wird meist nach ein bis drei Mal Niesen abgeschlossen.\n\nBeschrieben hat ihn schon Aristoteles, der ihn allerdings der Wärme der Sonne zuschrieb. Für Kampfpiloten und Skispringer ist er tatsächlich ein Thema – ein Nieser beim Verlassen eines Tunnels kommt zum ungünstigsten Zeitpunkt.',NULL,'Körper'),
(75,'Warum werden Haare grau?','Sie lagern mit dem Alter weißes Keratin ein','Die Farbstoffzellen in der Haarwurzel geben auf','Luft dringt in den Haarschaft ein','B','Die Farbe eines Haares kommt von Melanozyten in der Wurzel, die dem wachsenden Haar Pigment beigeben. Deren Nachschub an Stammzellen erschöpft sich mit den Jahren; kommt kein Pigment mehr, wächst das Haar farblos nach. Es wirkt weiß, weil Licht in ihm gestreut wird. Grau ist nur der Mischeindruck aus weißen und noch pigmentierten Haaren.\n\nEin einzelnes Haar wird also nicht grau – es wächst grau nach. Als Beschleuniger gilt außerdem Wasserstoffperoxid, das sich in der Wurzel anreichert und Pigment bleicht. Dass Haare über Nacht vom Schreck weiß werden, ist dagegen physikalisch unmöglich.',NULL,'Körper'),
(76,'Warum haben Männer Brustwarzen?','Sie sind ein Rest aus der Evolution der Säugetiere','Alle Embryonen legen sie an, bevor Hormone wirken','Sie erfüllen eine Aufgabe bei der Temperaturregelung','B','In den ersten Wochen entwickeln sich alle Embryonen nach demselben Bauplan, und dazu gehört die Anlage der Brustdrüsen. Erst danach steuern Hormone die weitere Entwicklung in eine Richtung. Die bereits angelegte Struktur wird nicht rückgebaut – sie bleibt einfach unentwickelt stehen.\n\nDass sie funktionsfähiges Gewebe ist, zeigt sich in Ausnahmen: Unter bestimmten hormonellen Bedingungen kann auch bei Männern Brustgewebe wachsen, und Männer können an Brustkrebs erkranken. Rund ein Prozent aller Fälle betrifft Männer – oft spät erkannt, weil niemand damit rechnet.',NULL,'Körper'),
(77,'Warum schmeckt Essen im Flugzeug fade?','Es wird zu lange warmgehalten','Trockene Luft, niedriger Druck und Lärm dämpfen den Geschmack','Die Bordküche darf kein Salz verwenden','B','Drei Dinge kommen zusammen. Die Kabinenluft ist extrem trocken, die Nasenschleimhaut nimmt Duftstoffe schlechter auf – und Geschmack ist zum größten Teil Geruch. Der reduzierte Druck dämpft zusätzlich. Und der Dauerlärm von rund 85 Dezibel senkt messbar die Wahrnehmung von süß und salzig. Etwa 30 Prozent Empfindlichkeit gehen verloren.\n\nEine Geschmacksrichtung bleibt weitgehend verschont und wird im Lärm sogar verstärkt: Umami. Genau deshalb ist Tomatensaft an Bord so beliebt, obwohl ihn am Boden kaum jemand bestellt – und deshalb würzen Airline-Küchen deutlich kräftiger, als es am Boden schmecken würde.',NULL,'Essen & Trinken'),
(78,'Warum hallt ein leerer Raum so stark?','Weil die Luft ohne Möbel besser schwingt','Weil Möbel und Textilien den Schall sonst aufnehmen','Weil der Schall an mehr Ecken gebrochen wird','B','Schall wird an harten, glatten Flächen fast vollständig zurückgeworfen und läuft im Raum hin und her, bis die Energie verbraucht ist. Weiche und poröse Dinge – Sofa, Teppich, Vorhang, Bücherregal, auch Menschen – nehmen ihn stattdessen auf und wandeln ihn in ein wenig Wärme um. Fehlen sie, dauert das Ausklingen deutlich länger.\n\nGenau diese Nachhallzeit ist die zentrale Größe der Raumakustik: In einem Wohnzimmer liegt sie bei etwa einer halben Sekunde, in einem leeren Neubau gern über zwei, in einer großen Kirche bei sechs oder mehr. Und weil Publikum stark absorbiert, klingt ein Konzertsaal bei der Probe anders als bei der Aufführung.',NULL,'Alltag'),
(79,'Warum kann man den Mond auch am helllichten Tag sehen?','Weil er hell genug ist, um sich gegen den blauen Himmel zu behaupten','Weil er näher ist als jeder Stern','Weil das Sonnenlicht ihn tagsüber zusätzlich anstrahlt','A','Der Mond ist kein Nachtobjekt – er steht schlicht dann am Himmel, wenn seine Bahn ihn dorthin führt, und das ist oft am Tag. Sichtbar ist er, weil seine Oberfläche genug Sonnenlicht zurückwirft, um heller zu sein als der gestreute blaue Himmel dahinter. Sterne schaffen das nicht, ihr Licht geht darin unter.\n\nAm besten gelingt es rund um die Halbmondphasen: Dann steht der Mond etwa 90 Grad von der Sonne entfernt, also hoch am Himmel, während die Sonne noch scheint. Bei Vollmond geht er dagegen ungefähr mit dem Sonnenuntergang auf – tagsüber ist er dann unter dem Horizont.',NULL,'Weltall'),
(80,'Warum haben fast alle Schrauben ein Rechtsgewinde?','Weil es für Rechtshänder beim Anziehen günstiger ist','Weil Linksgewinde sich leichter von selbst lösen','Weil die ersten Gewindeschneidmaschinen nur so arbeiten konnten','A','Beim Anziehen mit der rechten Hand ist die Drehung im Uhrzeigersinn kräftiger und kontrollierter als die Gegenrichtung – der Unterarm dreht dabei nach innen. Da die meisten Menschen Rechtshänder sind, setzte sich diese Richtung als Norm durch und wurde später einfach festgeschrieben.\n\nLinksgewinde gibt es dort, wo die Norm gefährlich wäre: an der linken Fahrradpedale, damit sie sich im Betrieb nicht losdreht, an manchen Sägeblattmuttern und an Gasflaschen für brennbare Gase, damit man keinen falschen Anschluss aufschraubt. Die Ausnahme ist also immer eine bewusste Sicherung.',NULL,'Geschichte'),
(81,'Was bedeutet »ok« ursprünglich?','Es ist die Abkürzung eines Ortsnamens','Es stammt von einem indianischen Wort für zustimmen','Es war ein Scherz mit absichtlich falscher Schreibung','C','1839 war in Bostoner Zeitungen eine Mode in Umlauf, Redewendungen absichtlich falsch zu schreiben und dann abzukürzen. »Oll korrect« für »all correct« wurde zu o.k. Die meisten dieser Scherzkürzel starben binnen Monaten – dieses eines nicht, weil es kurz darauf im Präsidentschaftswahlkampf eine zweite Bedeutung bekam.\n\nMartin Van Buren stammte aus Kinderhook und wurde »Old Kinderhook« genannt; seine Anhänger gründeten O.K.-Clubs. Beides zusammen machte die zwei Buchstaben unsterblich – heute gilt »ok« als das international am weitesten verbreitete Wort überhaupt.',NULL,'Sprache'),
(82,'Woher kommt das Wort »Panik«?','Von einem mittelalterlichen Arzt, der es beschrieb','Von einem lateinischen Wort für Flucht','Von einem griechischen Gott','C','Pan war der griechische Hirtengott mit Ziegenbeinen, zuständig für Wälder und Weiden. Ihm wurde nachgesagt, Wanderer und ganze Herden mit einem plötzlichen Schrecken zu überfallen – ein grundloses Entsetzen, das ohne erkennbaren Anlass durch die Menge lief. Dieser panische Schrecken wurde zum Wort.\n\nAuf ihn geht noch mehr zurück: die Panflöte, die er der Sage nach erfand, und über einen Umweg die christliche Teufelsdarstellung mit Hörnern und Ziegenfüßen. Das Wort »Pandemie« hat dagegen nichts mit ihm zu tun – das ist griechisch »das ganze Volk«.',NULL,'Sprache'),
(83,'Warum riecht es nach Regen so charakteristisch?','Tropfen schleudern Bodenöle und Bakteriensporen in die Luft','Blitze erzeugen Ozon in Bodennähe','Verdunstendes Wasser nimmt Staubgeruch mit','A','Trifft ein Tropfen auf trockenen Boden, schließt er kurz Luft ein. Die entweicht als Schwarm winziger Bläschen und reißt Stoffe von der Oberfläche mit: pflanzliche Öle, die sich in Trockenzeiten ablagern, und den Duftstoff Geosmin aus Bodenbakterien. Der Vorgang wurde mit Hochgeschwindigkeitskameras sichtbar gemacht.\n\nGeosmin ist der Hauptträger dieses Erdgeruchs, und die menschliche Nase ist dafür extrem empfindlich – wenige Teile pro Billion genügen. Derselbe Stoff macht Rote Bete erdig und ist der Grund, warum ein einzelner Tropfen Regenwasser im Trinkwasser sofort auffällt. Der Name für den Duft: Petrichor.',NULL,'Natur'),
(84,'Warum ist Schnee weiß, Eis aber durchsichtig?','Schnee enthält eingeschlossene Luft, die das Licht streut','Schneekristalle haben eine weiße Eigenfarbe','Schnee reflektiert nur Licht von der Oberfläche','A','Schnee ist nichts anderes als Eis – nur besteht er aus Millionen winziger Kristalle mit Luft dazwischen. An jeder Grenze zwischen Eis und Luft wird Licht ein Stück abgelenkt. Nach unzähligen Ablenkungen verlässt es den Schnee in alle Richtungen und in allen Farben gleichmäßig: Das nehmen wir als Weiß wahr.\n\nDasselbe Prinzip macht Zuckerwatte, Schaum und Wolken weiß, obwohl ihre Bestandteile klar sind. Und wo Schnee tief und dicht gepresst ist, sieht man den nächsten Effekt: In Gletschern wird nach langem Weg rotes Licht doch absorbiert – deshalb leuchtet Gletschereis blau.',NULL,'Natur'),
(85,'Warum bleibt Wasser in einem Eimer, den man im Kreis herumschleudert?','Eine Kraft drückt es nach außen an den Boden','Der Eimerboden zwingt es fortwährend auf die Kreisbahn','Die Luftströmung hält es im Eimer','B','Nach Trägheit will das Wasser geradeaus weiterfliegen. Der Eimerboden steht ihm dabei ständig im Weg und lenkt es nach innen um – diese nach innen gerichtete Kraft hält es auf der Kreisbahn. Am höchsten Punkt übernimmt die Schwerkraft einen Teil davon, den Rest liefert weiter der Boden. Wird zu langsam geschleudert, reicht die Schwerkraft allein nicht als Kurvenkraft aus, und das Wasser fällt heraus.\n\nDie oft genannte Zentrifugalkraft »nach außen« gibt es nur als Rechenhilfe für einen Beobachter, der sich mitdreht. Von außen betrachtet wirkt keine nach außen gerichtete Kraft – es wirkt nur zu wenig nach innen.',NULL,'Physik'),
(86,'Warum haben Flugzeugflügel oft nach oben gebogene Enden?','Um den Wirbel an der Flügelspitze zu bremsen','Um bei Bodenmanövern Platz zu sparen','Um dem Flügel mehr Stabilität zu geben','A','An der Flügelspitze trifft der Überdruck von unten auf den Unterdruck oben und rollt sich zu einem kräftigen Wirbel auf. Dieser Wirbel kostet Energie, ohne Auftrieb zu bringen. Ein aufgestelltes Ende – Winglet oder gebogene Spitze – erschwert dieses Umströmen und schwächt den Wirbel ab. Je nach Bauart bringt das mehrere Prozent Kraftstoffersparnis.\n\nDie Wirbel sind mehr als eine Detailfrage: Sie sind der Grund für die vorgeschriebenen Abstände zwischen startenden Flugzeugen, weil ein Wirbelschlepp ein kleineres Flugzeug hinter einem großen umwerfen kann. Bei Zugvögeln nutzt der Formationsflug denselben Effekt aus – der Nachfolger fliegt im Aufwind des Vordermanns.',NULL,'Technik'),
(87,'Warum ist es im Weltall kalt, obwohl die Sonne dort ungefiltert scheint?','Weil ohne Materie kaum Wärme übertragen werden kann','Weil die Sonnenstrahlung sich mit der Entfernung fast verliert','Weil die Temperatur im Vakuum grundsätzlich null ist','A','Temperatur ist die Bewegung von Teilchen – wo fast keine sind, gibt es kaum etwas zu erwärmen. Auf der Erde geben Luft und Wasser Wärme durch Berührung und Strömung weiter; im Vakuum fällt beides weg, es bleibt nur Strahlung. Ein Objekt in der Sonne wird darum sehr heiß, im Schatten sehr kalt, und zwischen beiden Seiten liegen Hunderte Grad.\n\nDaher ist Kühlen im All das eigentliche Problem, nicht Heizen: Die Raumstation trägt große Radiatoren, um Abwärme loszuwerden. Und Raumanzüge sind nicht dick gegen Kälte, sondern isolieren nach beiden Seiten und haben ein eigenes Kühlsystem gegen die Körperwärme.',NULL,'Weltall'),
(88,'Warum hat die Zahnpasta-Tube oben ein farbiges Rechteck?','Es ist eine Markierung für die Schneidemaschine','Es verschlüsselt die Inhaltsstoffe','Es zeigt die Herkunft der Rohstoffe an','A','Die farbigen Kästchen sind Passermarken für die Verpackungsmaschine. Ein Lichtsensor erkennt den Farbblock gegen den hellen Untergrund und weiß dadurch genau, an welcher Stelle die endlose Tubenbahn geschnitten und versiegelt werden muss. Die Farbe selbst ist beliebig – sie muss nur genug Kontrast liefern.\n\nEntsprechend ist die verbreitete Erzählung frei erfunden, grün stehe für rein natürliche und schwarz für rein chemische Inhaltsstoffe. Dieselben Marken finden sich an Chipstüten, Kaffeeverpackungen und Wurstfolien, wo niemand eine geheime Botschaft vermutet.',NULL,'Alltag'),
(89,'Warum wird ein Handyakku im Winter draußen so schnell leer?','Die chemischen Vorgänge im Akku laufen langsamer','Das Display braucht bei Kälte mehr Strom','Der Akku verliert bei Kälte tatsächlich Ladung','A','In einem Lithium-Ionen-Akku müssen Ionen durch einen Elektrolyten wandern. Bei Kälte wird der zäher und die Wanderung langsamer, der Innenwiderstand steigt. Der Akku kann die geforderte Leistung nicht mehr liefern, die Spannung bricht unter Last ein, und die Elektronik deutet das als »leer« und schaltet ab. Die Energie ist dabei nicht verloren – im Warmen zeigt das Gerät oft wieder Ladung an.\n\nWichtig ist die Folge fürs Laden: Ein Akku unter null Grad sollte nicht geladen werden, weil sich dann metallisches Lithium abscheiden kann, was ihn dauerhaft schädigt. Gute Geräte verweigern das Laden bei Kälte deshalb von selbst.',NULL,'Technik'),
(90,'Warum sind die Gleise in vielen Ländern genau 1435 Millimeter breit?','Das Maß ergab sich aus Berechnungen zur Kurvenstabilität','Es entspricht der Breite eines römischen Streitwagens','Es übernahm das Maß englischer Kohlebahnen','C','George Stephenson baute seine Lokomotiven für Kohlebahnen im Nordosten Englands, deren Spurweite sich aus dem örtlichen Fuhrwerksbau ergeben hatte. Als seine Maschinen sich durchsetzten, wurde deren Maß mitgeliefert und später als Normalspur festgeschrieben – gut 1435 Millimeter, also vier Fuß achteinhalb Zoll.\n\nDie beliebte Erzählung, das Maß gehe auf die Achsbreite römischer Streitwagen zurück, ist eine Legende ohne Belege. Dass verschiedene Länder bewusst andere Spurweiten wählten, hatte oft militärische Gründe: Eine abweichende Spur bremst einen Angreifer, weil er seine Züge nicht einfach weiterfahren lassen kann.',NULL,'Geschichte');
